INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "ライラエル", 0.0, 2, 2, 126501, 10003, "2023/09/22 14:59:59", -470.0, 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 0.0, "2023/06/30 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, "ライラエル", 0.0, 1, 1, 126501, 10004, "2023/09/22 14:59:59", -470.0, 2, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 0.0, "2023/06/30 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "リンド", 0.0, 2, 2, 127702, 10005, "2023/12/22 14:59:59", -470.0, 1, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 0.0, "2023/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "リンド", 0.0, 2, 2, 127702, 10006, "2023/12/22 14:59:59", -470.0, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 0.0, "2023/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "ヴルム", 0.0, 1, 1, 127802, 10007, "2023/12/22 14:59:59", -470.0, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 0.0, "2023/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, "ヴルム", 0.0, 2, 1, 127802, 10008, "2023/12/22 14:59:59", -470.0, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 6.5, "2023/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "アネモネ", 0.0, 2, 1, 129602, 10009, "2024/03/22 14:59:59", -470.0, 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 0.0, "2023/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "アネモネ", 0.0, 2, 1, 129602, 10010, "2024/03/22 14:59:59", -470.0, 2, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 0.0, "2023/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "ネフィ=ネラ", 0.0, 1, 1, 129701, 10011, "2024/03/22 14:59:59", -470.0, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 0.0, "2023/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, "ネフィ=ネラ", 0.0, 2, 1, 129701, 10012, "2024/03/22 14:59:59", -470.0, 2, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 6.2, "2023/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "カノン", 0.0, 3, 5, 130301, 10013, "2024/06/22 14:59:59", -470.0, 1, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 3.1, "2024/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "カノン", 0.0, 3, 2, 130301, 10014, "2024/06/22 14:59:59", -470.0, 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 6.15, "2024/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "ナーナ", 0.0, 2, 2, 130401, 10015, "2024/06/22 14:59:59", -470.0, 1, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 0.0, "2024/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, "ナーナ", 0.0, 2, 1, 130401, 10016, "2024/06/22 14:59:59", -470.0, 2, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 3.35, "2024/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", 0.0, 1, 1, 130502, 10017, "2024/09/22 14:59:59", -470.0, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 0.0, "2024/06/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", 0.0, 2, 1, 130502, 10018, "2024/09/22 14:59:59", -470.0, 2, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 3.18, "2024/06/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ホウオウ", 0.0, 4, 4, 130503, 10019, "2024/09/22 14:59:59", -470.0, 3, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 0.0, "2024/06/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ネア", 0.0, 1, 2, 123301, 10020, "2024/09/22 14:59:59", -470.0, 1, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 4.9, "2024/06/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, "ネア", 0.0, 1, 2, 123301, 10021, "2024/09/22 14:59:59", -470.0, 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 4.8, "2024/06/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "カリザ", 0.0, 3, 1, 133301, 10022, "2024/12/22 14:59:59", -470.0, 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 4.922, "2024/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "カリザ", 0.0, 3, 5, 133301, 10023, "2024/12/22 14:59:59", -470.0, 2, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 9.638, "2024/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "ミーア", 0.0, 1, 2, 133401, 10024, "2024/12/22 14:59:59", -470.0, 1, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2.88, "2024/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, "ミーア", 0.0, 5, 1, 133401, 10025, "2024/12/22 14:59:59", -470.0, 2, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 4.818, "2024/09/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "グレイス", 0.0, 2, 1, 133002, 10026, "2025/03/22 14:59:59", -470.0, 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1.78, "2024/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "グレイス", 0.0, 1, 7, 133002, 10027, "2025/03/22 14:59:59", -470.0, 2, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 6.15, "2024/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "ヴァイオレット", 0.0, 6, 2, 133102, 10028, "2025/03/22 14:59:59", -470.0, 1, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 4.28, "2024/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, "ヴァイオレット", 0.0, 1, 1, 133102, 10029, "2025/03/22 14:59:59", -470.0, 2, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 0.0, "2024/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "ルルィ", 0.0, 2, 1, 136902, 10030, "2025/06/23 14:59:59", -470.0, 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 5.53, "2025/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "ルルィ", 0.0, 9, 7, 136902, 10031, "2025/06/23 14:59:59", -470.0, 2, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 6.05, "2025/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "デュラン", 0.0, 2, 1, 137001, 10032, "2025/06/23 14:59:59", -470.0, 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 0.0, "2025/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, "デュラン", 0.0, 2, 1, 137001, 10033, "2025/06/23 14:59:59", -470.0, 2, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 0.0, "2025/03/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "サツキ", 0.0, 2, 2, 135902, 10034, "2025/09/23 14:59:59", -470.0, 1, "おう\n好きなもん持ってきな", 0.0, "2025/06/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "サツキ", 0.0, 1, 6, 135902, 10035, "2025/09/23 14:59:59", -470.0, 2, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 4.935, "2025/06/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "ユキノ", 0.0, 2, 5, 135802, 10036, "2025/09/23 14:59:59", -470.0, 1, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 7.441, "2025/06/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, "ユキノ", 0.0, 7, 7, 135802, 10037, "2025/09/23 14:59:59", -470.0, 2, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 0.0, "2025/06/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "クルル", 0.0, 2, 2, 130901, 10038, "2025/12/22 14:59:59", -470.0, 1, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2.295, "2025/09/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "クルル", 0.0, 1, 6, 130901, 10039, "2025/12/22 14:59:59", -470.0, 2, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6.281, "2025/09/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "ヴォルガーノ", 0.0, 2, 1, 137701, 10040, "2025/12/22 14:59:59", -470.0, 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 5.549, "2025/09/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, "ヴォルガーノ", 0.0, 3, 6, 137701, 10041, "2025/12/22 14:59:59", -470.0, 2, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2.64, "2025/09/16 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "ライラエル", 0.0, 7, 4, 132801, 10042, "2026/03/23 11:59:59", -470.0, 1, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 7.642, "2025/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "ライラエル", 0.0, 1, 1, 132802, 10043, "2026/03/23 11:59:59", -470.0, 2, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 0.0, "2025/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "クローチェ", 0.0, 1, 1, 134502, 10044, "2026/03/23 11:59:59", -470.0, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 0.0, "2025/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, "クローチェ", 0.0, 2, 1, 134501, 10045, "2026/03/23 11:59:59", -470.0, 2, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 3.72, "2025/12/15 15:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "ネフィ＝ネラ", 0.0, 2, 1, 138201, 10046, "2026/06/22 11:59:59", -470.0, 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 4.991, "2026/03/16 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "ネフィ＝ネラ", 0.0, 1, 4, 138201, 10047, "2026/06/22 11:59:59", -470.0, 2, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 3.877, "2026/03/16 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "アラクネ", 0.0, 4, 6, 136001, 10048, "2026/06/22 11:59:59", -470.0, 1, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 1.71, "2026/03/16 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, "アラクネ", 0.0, 5, 2, 136001, 10049, "2026/06/22 11:59:59", -470.0, 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 5.32, "2026/03/16 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "アネモネ", 0.0, 9, 4, 135401, 10050, "2026/09/22 11:59:59", -470.0, 1, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 3.727, "2026/06/15 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "アネモネ", 0.0, 7, 9, 135401, 10051, "2026/09/22 11:59:59", -470.0, 2, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 7.213, "2026/06/15 12:00:00", 2002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, "クリア", 0.0, 1, 2, 135301, 10052, "2026/09/22 11:59:59", -470.0, 1, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 1.874, "2026/06/15 12:00:00", 2002);
